/** The bounds of the whole country, for a map that wants to fit it to a box. */
export const BD_BOUNDS = { west: 88.009, east: 92.68, south: 20.74, north: 26.635 }

/** Build an SVG path from a ring, with whatever projection the caller draws in. */
export function ringPath(ring: Ring, project: (lon: number, lat: number) => [number, number]): string {
  let d = ''
  for (let i = 0; i < ring.length; i += 1) {
    const [px, py] = project(ring[i]![0], ring[i]![1])
    d += `${i ? 'L' : 'M'}${px.toFixed(1)} ${py.toFixed(1)}`
  }
  return `${d}Z`
}

/** The attribution the licence requires, shown on every map that draws these. */
export const BD_DISTRICTS_SOURCE = 'Boundaries: geoBoundaries gbOpen BGD ADM2, CC BY 4.0'
